import { Input, Button, Typography } from 'antd'
import { PlusOutlined, DeleteOutlined } from '@ant-design/icons'

const { Text } = Typography

// The template's table "Format | Extension | Software used / file specification".
// Rows come from the generated file structure and stay fully editable.
export default function FormatsTable({ rows, onChange }) {
  const update = (i, patch) => onChange(rows.map((r, idx) => idx === i ? { ...r, ...patch } : r))
  const remove = (i) => onChange(rows.filter((_, idx) => idx !== i))
  const add = () => onChange([...rows, { format: '', extension: '', software: '' }])

  return (
    <div style={{ marginBottom: 20 }}>
      <div style={{ fontWeight: 500, fontSize: 14, marginBottom: 2 }}>File formats</div>
      <Text style={{ fontSize: 12, color: 'rgba(0,0,0,0.45)', display: 'block', marginBottom: 6 }}>
        List all file formats and which software created the files. If files were made manually,
        explain their internal structure (e.g. column headers). This becomes a table in the Word file.
      </Text>
      {rows.length > 0 && (
        <div style={{ display: 'grid', gridTemplateColumns: '1.2fr 0.6fr 2.2fr 32px', gap: 6, alignItems: 'start' }}>
          <Text strong style={{ fontSize: 12 }}>Format</Text>
          <Text strong style={{ fontSize: 12 }}>Extension</Text>
          <Text strong style={{ fontSize: 12 }}>Software used / file specification</Text>
          <span />
          {rows.map((r, i) => (
            <FormatRow key={i} row={r} onChange={(p) => update(i, p)} onRemove={() => remove(i)} />
          ))}
        </div>
      )}
      <Button type="dashed" size="small" icon={<PlusOutlined />} onClick={add} style={{ marginTop: 8, width: '30%' }}>
        Add a file format
      </Button>
    </div>
  )
}

function FormatRow({ row, onChange, onRemove }) {
  return (
    <>
      <Input size="small" value={row.format} onChange={e => onChange({ format: e.target.value })}
        placeholder="e.g. Tab-Separated Values" />
      <Input size="small" value={row.extension} onChange={e => onChange({ extension: e.target.value })} placeholder="tsv" />
      <Input.TextArea size="small" value={row.software} onChange={e => onChange({ software: e.target.value })}
        autoSize={{ minRows: 1, maxRows: 5 }}
        placeholder={row.example ? `e.g. ${row.example}: generated by …` : 'Software, version, file specification'} />
      <Button size="small" type="text" danger icon={<DeleteOutlined />} onClick={onRemove} />
    </>
  )
}
